// src/badminton/stage.ts
var SPAWN1 = actor_geometry_default.markers.gunnerPoint;
var SPAWN2 = actor_geometry_default.markers.gunnerPoint2;
var HZ2 = 30;
var STEP_MS2 = 1e3 / HZ2;
var TARGET = 7;
var GROUND = runtime_geometry_default.ground;
var LEFT_WALL = 36.5;
var RIGHT_WALL = 513.5;
var NET_X = runtime_geometry_default.net.x;
var NET_TOP = runtime_geometry_default.net.y - runtime_geometry_default.net.height / 2;
var NET_HALF_WIDTH = runtime_geometry_default.net.width / 2;
var NET_LIMIT_X = runtime_geometry_default.netLimit.x;
var NET_LIMIT_HALF_WIDTH = runtime_geometry_default.netLimit.width / 2;
var NET_LIMIT_TOP = runtime_geometry_default.netLimit.y - runtime_geometry_default.netLimit.height / 2;
var NET_LIMIT_BOTTOM = runtime_geometry_default.netLimit.y + runtime_geometry_default.netLimit.height / 2;
var twips = (value2) => Math.trunc(value2 * 20) || 0;
var pixel = (value2) => twips(value2) / 20;
var rotation = (vx, vy) => Math.atan2(vy, vx) / 3.141593 * 180 + 90;
var wrapRotation = (degrees) => ((degrees + 180) % 360 + 360) % 360 - 180;

// src/badminton/geometry.ts
function racketFramePose(seat, frame2, profile) {
  if (profile) {
    const poses3 = actor_geometry_default.actors[profile].hitboxes, pose4 = poses3[Math.max(0, Math.min(poses3.length - 1, frame2 - 1))];
    return { ...pose4, bounds: pose4.twips.map((v) => v / 20) };
  }
  const poses2 = seat === 1 && frame2 >= 16 ? geometry_default.timelines["p1-underhand"] : seat === 1 ? geometry_default.timelines["p1-swing"] : geometry_default.timelines["p2-swing"];
  const pose3 = poses2[Math.max(0, Math.min(poses2.length - 1, frame2 >= 16 ? frame2 - 16 : frame2 - 1))];
  return { ...pose3, rotation: pose3.native.rotation, bounds: pose3.native.twips.map((v) => v / 20) };
}
function racketFrameContains(p, seat, frame2, x, y, profile) {
  const pose3 = racketFramePose(seat, frame2, profile), [left, top, right, bottom] = pose3.bounds;
  const px = twips(x) - twips(p.x), py = twips(y) - twips(p.y);
  return pose3.active && px >= Math.round(left * 20) && px <= Math.round(right * 20) && py >= Math.round(top * 20) && py <= Math.round(bottom * 20);
}
function servePoint(seat, frame2, profile) {
  if (profile) {
    const poses2 = actor_geometry_default.actors[profile].service, pose4 = poses2[Math.max(0, Math.min(poses2.length - 1, frame2 - 1))];
    return { x: pose4.x, y: pose4.y };
  }
  const pose3 = (seat === 1 ? geometry_default.timelines["p1-serve"] : geometry_default.timelines["p2-serve"])[Math.max(0, Math.min(12, frame2 - 1))];
  return { x: pose3.point[0], y: pose3.point[1] };
}

// src/badminton/control.ts
function controlState() {
  return {
    jumping: false,
    jumps: 0,
    motion: "normal",
    motionAt: 0,
    racket: { frame: 1, playing: false, serveFrame: 1, servePlaying: false, ready: true, active: false, consumed: false, angle: 0, strokes: 0, strokeAt: -1 }
  };
}
